sys_script_include.script:
var call_ikkatu = Class.create();
call_ikkatu.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    call: function(sys_id) {
        var gr = new GlideRecord('x_1882833_organi_0_jinji_idou');
        gr.addQuery('sys_id', sys_id);
        gr.query();

        if (gr.next()) {

            var api = new Ikkatusinsei();
            var answer = api.ikkatu(gr.sys_id, gr.sinsei_shubetu);
            gr.update();

            if (answer != "OK") {

                if (answer == "添付無し") {
                    gs.addErrorMessage('一括申請用のExcelファイルは必須です。少なくとも1件添付してください。');

                } else if (answer == "フォーマット違い") {
                    gs.addErrorMessage('Excelファイルのフォーマットが違います。内容を確認して再添付してください。');

                } else if (answer == "データ不足") {
                    gs.addErrorMessage('必須データが入力されていません。');

                } else if (answer == "エラー") {
                    gs.addErrorMessage('エラー');
                }

            }
        }
    },
    type: 'call_ikkatu'
});
